const TEMA = ["terang", "gelap", "sistem"] as const;
type Tema = (typeof TEMA)[number];
type Pengaturan = { tema: Tema; ukuranHuruf: number; notifikasi: boolean };
const BAWAAN: Readonly<Pengaturan> = { tema: "sistem", ukuranHuruf: 14, notifikasi: true };

type Aturan = { [K in keyof Pengaturan]: (v: Pengaturan[K]) => string | null };
const ATURAN: Aturan = {
  tema: () => null,
  ukuranHuruf: (v) => (v >= 12 && v <= 24 ? null : "Ukuran huruf 12 sampai 24"),
  notifikasi: () => null,
};
const sekarang: Pengaturan = { ...BAWAAN };
function ubah<K extends keyof Pengaturan>(kunci: K, nilai: Pengaturan[K]): string {
  const pesan = ATURAN[kunci](nilai);
  if (pesan) return "Ditolak: " + pesan;
  sekarang[kunci] = nilai;
  return "OK";
}
console.log(ubah("tema", "gelap"));
console.log(ubah("ukuranHuruf", 40));
console.log(sekarang.tema, sekarang.ukuranHuruf);

