const LEVEL = ["perunggu", "perak", "emas"] as const;
type Level = (typeof LEVEL)[number];
const minimal: Record<Level, number> = { perunggu: 0, perak: 100, emas: 500 };
function level(poin: number): Level {
  let hasil: Level = "perunggu";
  for (const l of LEVEL) if (poin >= minimal[l]) hasil = l;
  return hasil;
}
console.log(level(120), level(800));

