type Pengaturan = { tema: string; bahasa: string; ukuranHuruf: number };
const p: Pengaturan = { tema: "gelap", bahasa: "id", ukuranHuruf: 16 };
type Ringkasan = Pick<Pengaturan, "tema" | "bahasa">;
function ringkas(x: Pengaturan): Ringkasan {
  return { tema: x.tema, bahasa: x.bahasa };
}
const LABEL: Record<keyof Ringkasan, string> = { tema: "Tema", bahasa: "Bahasa" };
const r = ringkas(p);
for (const k of ["tema", "bahasa"] as const) {
  console.log(LABEL[k] + ": " + r[k]);
}
